import {vehicleForPerson,participantRole} from './transport.mjs';
import {journeysForPerson} from './document-model.mjs';
export function participantProgress(trip,person){
 const journeys=journeysForPerson(trip,person.id),vehicle=vehicleForPerson(trip,person,'Anada');
 const checks=[
  {key:'journeys',label:'Trajectes',done:person.ticket==='No cal'||(journeys.length>0&&journeys.every(s=>s.origin&&s.destination&&s.departure&&s.arrival&&!s.pending&&!s.stale)),detail:journeys.length?`${journeys.length} trajectes${journeys.some(s=>s.pending||s.stale)?' · revisar':''}`:person.ticket==='No cal'?'No cal':'Sense trajectes',action:journeys.length?'person-documents':'edit-person'},
  {key:'ticket',label:'Bitllet',done:['Comprat','No cal'].includes(person.ticket),detail:person.ticket==='Comprat'?'OK · Comprat':person.ticket||'Pendent',action:'edit-person'},
  {key:'checkin',label:'Check-in',done:['Fet','No cal'].includes(person.checkin),detail:person.checkin||'Pendent',action:'person-checkin'},
  {key:'pickup',label:'Recollida',done:!!person.pickup||!!(vehicle?.driver&&vehicle?.origin&&vehicle?.departure),detail:person.pickup|| (vehicle?`${vehicle.name}${vehicle.driver&&vehicle.origin&&vehicle.departure?'':' · incomplet'}`:'Sense assignar'),action:'edit-person'}
 ];
 return {person,checks,pending:checks.filter(c=>!c.done),complete:checks.every(c=>c.done)};
}
export function renderDashboard(trip,filter,esc){
 const rows=trip.people.map(p=>participantProgress(trip,p)),ready=rows.filter(r=>r.complete).length,total=rows.length,ratio=total?Math.round(100*ready/total):0;
 const shown=rows.filter(r=>filter==='all'||(filter==='pending'?r.pending.length:r.pending.some(c=>c.key===filter)));
 const filters=[['all','Tothom'],['pending','Amb pendents'],['journeys','Trajectes'],['ticket','Bitllet'],['checkin','Check-in'],['pickup','Recollida']];
 return `<section class="trip-dashboard"><div class="readiness-banner"><div><span class="eyebrow">CONTROL DEL VIATGE</span><h2>${ready} de ${total} participants a punt</h2><p>${total-ready} amb gestions pendents · ${rows.reduce((n,r)=>n+r.pending.length,0)} comprovacions per completar</p></div><div class="readiness-meter"><strong>${ratio}%</strong><progress value="${ready}" max="${total||1}" aria-label="Participants amb totes les comprovacions completes"></progress></div></div><div class="dashboard-filters" role="group" aria-label="Filtrar participants">${filters.map(([key,label])=>`<button class="button secondary ${filter===key?'selected-filter':''}" data-action="dashboard-filter" data-id="${key}" aria-pressed="${filter===key}">${label}${key==='all'?'':` · ${rows.filter(r=>key==='pending'?r.pending.length:r.pending.some(c=>c.key===key)).length}`}</button>`).join('')}</div>${shown.length?`<div class="table-wrap"><table class="readiness-table"><thead><tr><th>PARTICIPANT</th><th>TRAJECTES</th><th>BITLLET</th><th>CHECK-IN</th><th>RECOLLIDA</th></tr></thead><tbody>${shown.map(r=>`<tr><td><button class="text-button" data-action="edit-person" data-id="${esc(r.person.id)}">${esc(r.person.name)}</button><small>${esc(participantRole(r.person.role))} · ${esc(r.person.travelMode||'Avió')}</small><small>${r.complete?'✓ A punt':`${r.pending.length} pendents`}</small></td>${r.checks.map(c=>`<td><button class="readiness-cell ${c.done?'complete':'incomplete'}" data-action="${c.action}" data-id="${esc(r.person.id)}" aria-label="${esc(r.person.name+' · '+c.label+' · '+c.detail)}"><b aria-hidden="true">${c.done?'✓':'!'}</b><span>${esc(c.detail)}</span></button></td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>${total?'Cap participant amb aquest pendent':'Encara no hi ha participants'}</h3><p>${total?'Canvia el filtre per veure la resta de l’equip.':'Vincula la carpeta i llegeix els documents per començar.'}</p></div>`}<p class="small muted">Prem una casella per completar-la.</p></section>`;
}
